parameters.jsCode:
// Pick daily product from catalog
const products = [
  {
    "id": "pur-001",
    "name": "Califnco HydroPure Elite RO+UV+UF+Copper",
    "price": 14999,
    "category": "purifiers",
    "description": "Advanced 8-stage RO purifier with copper infusion technology and active mineral balance."
  },
  {
    "id": "pur-006",
    "name": "Califnco Smart IoT RO with Mobile App Sync",
    "price": 21999,
    "category": "purifiers",
    "description": "Smart WiFi-enabled RO purifier displaying real-time water purity, input/output TDS, and filter life."
  },
  {
    "id": "dis-001",
    "name": "Califnco Commercial 3-Tap Floor RO Dispenser",
    "price": 29999,
    "category": "dispensers",
    "description": "Heavy-duty 3-temperature floor standing dispenser with built-in 50 LPH RO purification."
  }
];

const dayOfYear = Math.floor((new Date() - new Date(new Date().getFullYear(), 0, 0)) / 1000 / 60 / 60 / 24);
const product = products[dayOfYear % products.length];

return [{ json: { product } }];

